import React from "react"

/**
 * The base surface for every dashboard section.
 *
 * The header renders only when there is something to put in it, and takes a
 * divider only when the body is flush against it (tables), so a padded body
 * does not get a redundant rule.
 */
export default function Panel({
  title,
  subtitle,
  actions,
  flush = false,
  divided = flush,
  className,
  children,
  as: Tag = "section",
}) {
  const hasHeader = Boolean(title || subtitle || actions)
  const classes = ["panel", className].filter(Boolean).join(" ")

  return (
    <Tag className={classes}>
      {hasHeader && (
        <div className={"panel__header" + (divided ? " panel__header--divided" : "")}>
          <div className="panel__heading">
            {title && <h2 className="panel__title">{title}</h2>}
            {subtitle && <p className="panel__subtitle">{subtitle}</p>}
          </div>
          {actions && <div className="panel__actions">{actions}</div>}
        </div>
      )}
      <div className={"panel__body" + (flush ? " panel__body--flush" : "")}>{children}</div>
    </Tag>
  )
}
