import React, { useState } from "react"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import TickerMark from "../components/ui/TickerMark"

import { risk, signals, backtests, options, source, generatedAt } from "../data/generated/engine-snapshot"

/**
 * Risk.
 *
 * What a signal would actually become: a share count, a dollar amount at risk,
 * and — where the answer is no — the check that said so.
 *
 * THE ARGUMENT THIS PAGE MAKES. Fixed-fractional sizing puts 10% of equity into
 * every trade and lets the stop decide the loss, so a trade stopped 2% away
 * loses 0.2% of the account and one stopped 15% away loses 1.5% — seven times
 * as much, from the same signal, with nobody ever having decided that. Risk-
 * based sizing inverts it: the dollar loss is fixed first and the share count
 * falls out of the stop. A wider stop therefore buys FEWER shares, and that is
 * the number the table is built to show.
 */

const DASH = "—"
const isNum = v => typeof v === "number" && Number.isFinite(v)
const num = (v, d = 2) => (isNum(v) ? v.toFixed(d) : DASH)
const usd = (v, d = 2) => (isNum(v) ? (v < 0 ? "−$" : "$") + Math.abs(v).toFixed(d) : DASH)
const pct = (v, d = 2) => (isNum(v) ? (v * 100).toFixed(d) + "%" : DASH)

export default function RiskPage({ location }) {
  const [openSymbol, setOpenSymbol] = useState(null)

  const decisions = risk.decisions
  const approved = decisions.filter(d => d.approved)
  const refused = decisions.filter(d => !d.approved)
  const signalFor = id => signals.find(s => s.id === id)

  return (
    <Shell location={location}>
      <div className="page">
        <header className="page__head">
          <div className="page__heading">
            <Breadcrumb items={[{ label: "MarketScan", to: "/" }, { label: "Risk" }]} />
            <h1 className="page__title">Risk</h1>
            <p className="page__lede">
              Every live signal, sized against a {usd(risk.equity, 0)} account. The strategy says
              whether it is a setup; it does not get to say how much.
            </p>
          </div>
          <div className="page__meta">
            <span className="page__meta-item">
              <span className="page__meta-label">Risk per trade</span>
              <span className="page__meta-value">{pct(risk.config.riskPerTradePct, 1)}</span>
            </span>
            <span className="page__meta-item">
              <span className="page__meta-label">Max position</span>
              <span className="page__meta-value">{pct(risk.config.maxPositionPct, 0)}</span>
            </span>
            <span className="page__meta-item">
              <span className="page__meta-label">Built</span>
              <span className="page__meta-value">{generatedAt.slice(0, 10)}</span>
            </span>
          </div>
        </header>

        <Panel
          title="Limits in force"
          subtitle="Every one of these can only ever REDUCE a position. Nothing here can raise one."
        >
          <div className="limit-grid">
            <Limit
              label="Risk per trade"
              value={pct(risk.config.riskPerTradePct, 1)}
              note={`${usd(risk.equity * risk.config.riskPerTradePct, 0)} of the account, entry to stop, on every trade regardless of how wide the stop is.`}
            />
            <Limit
              label="Single position cap"
              value={pct(risk.config.maxPositionPct, 0)}
              note="The backstop against a sizing mistake: a very tight stop would otherwise buy an enormous position for the same nominal risk."
            />
            <Limit
              label="Portfolio exposure"
              value={pct(risk.config.maxPortfolioExposurePct, 0)}
              note="Total invested capital as a share of equity."
            />
            <Limit
              label="Minimum stop distance"
              value={pct(risk.config.minStopDistancePct, 2)}
              note="A stop inside the noise is not a stop; it is a scheduled exit with a cost."
            />
            <Limit
              label="Daily loss kill switch"
              value={pct(risk.config.maxDailyLossPct, 0)}
              note="Measured against the day's opening equity. Clears at the next session."
            />
            <Limit
              label="Drawdown kill switch"
              value={pct(risk.config.maxDrawdownPct, 0)}
              note="Peak-to-trough. Survives the date changing, and needs an explicit reset — the equity that caused it has not come back just because it is tomorrow."
            />
          </div>
        </Panel>

        <Panel
          title="Live signals, sized"
          subtitle={
            decisions.length
              ? `${approved.length} approved, ${refused.length} refused. Every refusal names the check that refused it.`
              : "No strategy fired on the most recent bar, so there is nothing to size."
          }
        >
          {decisions.length === 0 ? (
            <p className="empty-note">
              An empty list here is an ordinary outcome, not a gap. The strategies were evaluated
              on every symbol's latest bar and none of them produced an entry.
            </p>
          ) : (
            <ul className="risk-list">
              {decisions.map(d => {
                const signal = signalFor(d.signalId)
                const open = openSymbol === d.symbol
                return (
                  <li className="risk-list__item" key={d.signalId}>
                    <span className="risk-list__symbol">
                      <TickerMark symbol={d.symbol} size={24} />
                      <br />
                      {d.symbol}
                    </span>

                    <span className="risk-list__reason">
                      <span
                        className={
                          "risk-list__code " +
                          (d.approved ? "risk-list__code--ok" : "risk-list__code--refused")
                        }
                      >
                        {d.code}
                      </span>
                      <br />
                      {d.reason}
                      {signal && (
                        <>
                          <br />
                          <span className="muted" style={{ fontSize: 12 }}>
                            {signal.strategyName} — {signal.trigger}
                          </span>
                        </>
                      )}
                      <br />
                      <button
                        type="button"
                        className="coverage__toggle"
                        style={{ marginLeft: 0, marginTop: 6 }}
                        onClick={() => setOpenSymbol(open ? null : d.symbol)}
                      >
                        {open ? "Hide checks" : `${d.checks.length} checks`}
                      </button>
                      {open && (
                        <table className="check-table">
                          <tbody>
                            {d.checks.map(c => (
                              <tr key={c.name} className={c.passed ? "" : "is-failed"}>
                                <td className="check-table__mark">{c.passed ? "✓" : "✗"}</td>
                                <td className="check-table__name">{c.name}</td>
                                <td className="check-table__detail">{c.detail}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      )}
                    </span>

                    <span className="risk-list__size">
                      {d.approved ? (
                        <>
                          {d.shares} sh
                          <small>{usd(d.riskAmount)} at risk</small>
                          <small>
                            stop {usd(d.stopPrice)} · {num((d.stopDistancePct || 0) * 100, 2)}% away
                          </small>
                          <small>bound by {d.boundBy}</small>
                        </>
                      ) : (
                        <>
                          0 sh<small>not sized</small>
                        </>
                      )}
                    </span>
                  </li>
                )
              })}
            </ul>
          )}
        </Panel>

        <Panel
          title="Why a wider stop buys fewer shares"
          subtitle="The same risk budget, three stop distances. This is the whole of risk-based sizing."
        >
          <table className="wf-table">
            <thead>
              <tr>
                <th>Stop distance</th>
                <th className="num">Risk per share</th>
                <th className="num">Shares</th>
                <th className="num">Position size</th>
                <th className="num">Loss at the stop</th>
              </tr>
            </thead>
            <tbody>
              {[0.02, 0.05, 0.1, 0.15].map(distance => {
                const price = 100
                const budget = risk.equity * risk.config.riskPerTradePct
                const perShare = price * distance
                const riskShares = Math.floor(budget / perShare)
                const capShares = Math.floor(
                  (risk.equity * Math.min(risk.config.maxPositionPct, risk.config.maxConcentrationPct)) / price
                )
                const shares = Math.min(riskShares, capShares)
                const capped = capShares < riskShares
                return (
                  <tr key={distance}>
                    <td>
                      {(distance * 100).toFixed(0)}% ({usd(price)} → {usd(price * (1 - distance))})
                    </td>
                    <td className="num">{usd(perShare)}</td>
                    <td className="num">
                      {shares}
                      {capped && <span className="muted"> (cap)</span>}
                    </td>
                    <td className="num">{usd(shares * price, 0)}</td>
                    <td className="num">{usd(shares * perShare, 0)}</td>
                  </tr>
                )
              })}
            </tbody>
          </table>
          <p className="empty-note" style={{ marginTop: 12 }}>
            The loss column is flat — that is the point. A losing streak costs a predictable
            amount instead of depending on which volatility regime the losers happened to land in.
            Where the position cap bites, the loss is smaller still: the cap can only ever reduce.
          </p>
        </Panel>

        <Panel
          title="Rejection vocabulary"
          subtitle="Every code the risk engine can return, with what it means. A UI that keeps its own copy of this list drifts out of step with the engine; this one is the engine's."
        >
          <table className="wf-table">
            <thead>
              <tr>
                <th>Code</th>
                <th>Kind</th>
                <th>Meaning</th>
              </tr>
            </thead>
            <tbody>
              {risk.codes.map(c => (
                <tr key={c.code}>
                  <td className="wf-table__params">{c.code}</td>
                  <td className="muted">{c.kind}</td>
                  <td>{c.description}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Panel>

        <Panel title="Options" subtitle="Implemented in full, and not entitled on this plan.">
          <div className="notice">
            <div>
              <p className="notice__title">Options data is blocked on {options.plan}</p>
              <p className="notice__text">{options.note}</p>
              <p className="notice__text">
                Blocked endpoints:{" "}
                {Object.values(options.endpoints).map((e, i) => (
                  <React.Fragment key={e}>
                    {i > 0 && ", "}
                    <code>{e}</code>
                  </React.Fragment>
                ))}
              </p>
            </div>
          </div>
        </Panel>
      </div>
    </Shell>
  )
}

function Limit({ label, value, note }) {
  return (
    <div className="limit">
      <span className="limit__label">{label}</span>
      <span className="limit__value">{value}</span>
      <span className="limit__note">{note}</span>
    </div>
  )
}

export const Head = () => <title>Risk · MarketScan</title>
